import{_ as t,o as a,c as s,a0 as n}from"./chunks/framework.DoRPXVp_.js";const u=JSON.parse('{"title":"Frequently Asked Questions","description":"","frontmatter":{},"headers":[],"relativePath":"faq/ebpf-sandbox.md","filePath":"faq/ebpf-sandbox.md"}'),o={name:"faq/ebpf-sandbox.md"};function r(i,e,d,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><p>Common questions and answers about Lattice internals, architecture, and design decisions.</p><h3 id="ebpf-policy-enforcement" tabindex="-1">eBPF &amp; Policy Enforcement <a class="header-anchor" href="#ebpf-policy-enforcement" aria-label="Permalink to &quot;eBPF &amp; Policy Enforcement&quot;">​</a></h3><ul><li><a href="#ebpf-vs-iptables">How does eBPF coexist with iptables?</a></li><li><a href="#pro-build-fix">Why did the PRO build fail with &quot;undefined: ebpf.NewManager&quot;?</a></li><li><a href="#build-tags">What is the PRO/Community build tag pattern?</a></li></ul><h3 id="agent-sandbox" tabindex="-1">Agent Sandbox <a class="header-anchor" href="#agent-sandbox" aria-label="Permalink to &quot;Agent Sandbox&quot;">​</a></h3><ul><li><a href="#sandbox-overview">How does the Agent sandbox work?</a></li><li><a href="#phase1-vs-phase2">What&#39;s the difference between Phase 1 and Phase 2 sandbox?</a></li><li><a href="#kernel-userspace-boundary">Is there a kernel-to-userspace boundary in the gVisor sandbox?</a></li><li><a href="#infra-vs-gvisor">Should infrastructure nodes use gVisor?</a></li></ul><hr><h2 id="ebpf-policy-enforcement-1" tabindex="-1">eBPF &amp; Policy Enforcement <a class="header-anchor" href="#ebpf-policy-enforcement-1" aria-label="Permalink to &quot;eBPF &amp; Policy Enforcement&quot;">​</a></h2><h3 id="ebpf-vs-iptables" tabindex="-1">eBPF vs iptables <a class="header-anchor" href="#ebpf-vs-iptables" aria-label="Permalink to &quot;eBPF vs iptables {#ebpf-vs-iptables}&quot;">​</a></h3><p><strong>Does eBPF replace all iptables rules in Lattice?</strong></p><p>No. eBPF only replaces the <strong>policy enforcement</strong> layer (allow/drop decisions on wf0). iptables is still used for:</p><table tabindex="0"><thead><tr><th>Responsibility</th><th>Implementation</th><th>Can eBPF replace it?</th></tr></thead><tbody><tr><td>Policy enforcement (allow/drop)</td><td>eBPF <code>tc_ingress</code> (PRO) / iptables (community)</td><td>✅ Yes</td></tr><tr><td>Docker NAT (MASQUERADE)</td><td>iptables</td><td>❌ No</td></tr><tr><td>FORWARD rules (wf0↔eth0)</td><td>iptables</td><td>❌ No</td></tr><tr><td>Community fallback</td><td>iptables</td><td>❌ No (kept intentionally)</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Policy layer:  eBPF TC ingress (PRO) or iptables (community)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Forwarding:    iptables FORWARD  ← needed for both PRO and community</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>NAT:           iptables MASQUERADE  ← needed for both, eBPF can&#39;t do this</span></span></code></pre></div><h3 id="pro-build-fix" tabindex="-1">PRO Build Fix <a class="header-anchor" href="#pro-build-fix" aria-label="Permalink to &quot;PRO Build Fix {#pro-build-fix}&quot;">​</a></h3><p><strong>Why did <code>make docker-build SERVICE=lattice EDITION=pro</code> fail with <code>undefined: ebpf.NewManager</code> and <code>undefined: ebpf.HaveProgramType</code>?</strong></p><p>Two issues introduced in commit <code>01f73381</code> (ebpf PR #221):</p><ol><li><p><strong><code>ebpf.NewManager</code> undefined</strong>: <code>manager_community.go</code> has <code>//go:build !pro</code> and provides a stub for community builds. When building with <code>-tags pro</code>, this file is excluded, but no <code>manager_pro.go</code> was created to provide the real implementation.</p></li><li><p><strong><code>ebpf.HaveProgramType</code> undefined</strong>: In cilium/ebpf v0.21.0, <code>HaveProgramType</code> moved from the root package to <code>github.com/cilium/ebpf/features</code>, and its signature changed from <code>(bool, error)</code> to <code>(error)</code> (nil = supported).</p></li></ol><p><strong>Fix:</strong></p><ul><li>Updated <code>enforcer_selector_pro.go</code> to use <code>features.HaveProgramType(ebpf.SchedCLS)</code> and check <code>err != nil</code>.</li><li>Created <code>internal/agent/ebpf/manager_pro.go</code> (<code>//go:build pro</code>) with the real eBPF Manager: loads TC ingress program, attaches via <code>link.AttachTCX</code>, and manages BPF maps.</li></ul><p>These issues weren&#39;t caught earlier because the PRO build path wasn&#39;t triggered in CI previously.</p><h3 id="build-tags" tabindex="-1">Build Tags <a class="header-anchor" href="#build-tags" aria-label="Permalink to &quot;Build Tags {#build-tags}&quot;">​</a></h3><p><strong>How does the PRO/Community build tag pattern work?</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//go:build pro      → compiled only with -tags pro (real implementation)</span></span>
<span class="line"><span>//go:build !pro     → community stub, returns 402 / &quot;Pro feature&quot; error</span></span>
<span class="line"><span>No build tag       → always compiled</span></span></code></pre></div><p>Makefile: <code>EDITION ?= community</code>. When <code>EDITION=pro</code>, <code>BUILD_TAGS := -tags pro</code> is set.</p><hr><h2 id="agent-sandbox-1" tabindex="-1">Agent Sandbox <a class="header-anchor" href="#agent-sandbox-1" aria-label="Permalink to &quot;Agent Sandbox&quot;">​</a></h2><h3 id="sandbox-overview" tabindex="-1">Sandbox Overview <a class="header-anchor" href="#sandbox-overview" aria-label="Permalink to &quot;Sandbox Overview {#sandbox-overview}&quot;">​</a></h3><p><strong>What is the Lattice Agent sandbox?</strong></p><p>The Agent sandbox ensures AI Agent network traffic is controlled by Lattice policy. It provides process-level isolation so that agents can only communicate with authorized destinations.</p><p>Two parallel approaches serve the same goal:</p><table tabindex="0"><thead><tr><th></th><th>Phase 1 (Kernel-assisted)</th><th>Phase 2 (User-space kernel)</th></tr></thead><tbody><tr><td>Interception point</td><td>Kernel eBPF TC hook on wf0</td><td>User-space Sentry netstack</td></tr><tr><td>Mechanism</td><td>cgroup + eBPF + seccomp notify</td><td>gVisor (user-space TCP/IP stack)</td></tr><tr><td>Privilege needed</td><td><code>CAP_NET_ADMIN</code> + <code>CAP_BPF</code></td><td><strong>Zero</strong></td></tr><tr><td>Performance</td><td>High (kernel-space)</td><td>Moderate (sufficient for agents)</td></tr><tr><td>Best for</td><td>Infrastructure nodes (DB, K8s mesh)</td><td>AI Agent sandboxes</td></tr></tbody></table><h3 id="phase1-vs-phase2" tabindex="-1">Phase 1 vs Phase 2 <a class="header-anchor" href="#phase1-vs-phase2" aria-label="Permalink to &quot;Phase 1 vs Phase 2 {#phase1-vs-phase2}&quot;">​</a></h3><p><strong>Are Phase 1 and Phase 2 progressive stages or alternative approaches?</strong></p><p>They are <strong>parallel implementations</strong>, not progressive stages. Both achieve the same goal (policy-controlled agent networking) but differ in where policy enforcement happens:</p><ul><li><strong>Phase 1</strong>: Policy enforced in the kernel (eBPF TC hook on wf0 TUN device). Higher performance, requires root.</li><li><strong>Phase 2</strong>: Policy enforced in user-space (gVisor Sentry Go netstack). Zero privilege, moderate performance.</li></ul><p>PRO users can choose per workload: infrastructure nodes use Phase 1 eBPF, AI agent sandboxes use Phase 2 gVisor.</p><p><strong>What is Phase 1&#39;s current implementation status?</strong></p><p>Phase 1 is <strong>not yet implemented</strong>. The design document exists, but <code>internal/agent/sandbox/</code>, <code>internal/agent/sidecar/</code>, and <code>internal/agent/ebpf/sandbox_bind.bpf.c</code> have not been created. The design also needs revision: it labels Phase 1 as &quot;community edition&quot; but heavily uses eBPF, which is a PRO feature.</p><p><strong>Revised layering:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Community Phase 1:</span></span>
<span class="line"><span>  cgroup resource limits (cpu/mem/io)</span></span>
<span class="line"><span>  + LD_PRELOAD socket interception (liblattice_intercept.so, zero privilege)</span></span>
<span class="line"><span>  + iptables policy enforcement</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PRO Phase 1 enhancement:</span></span>
<span class="line"><span>  All of community</span></span>
<span class="line"><span>  + eBPF PID→TUN binding (cgroup/connect4, zero seccomp overhead)</span></span>
<span class="line"><span>  + eBPF fast path (whitelist hit bypasses seccomp)</span></span>
<span class="line"><span>  + eBPF TC ingress policy (replaces iptables)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PRO Phase 2:</span></span>
<span class="line"><span>  gVisor full user-space isolation (zero privilege, ✅ implemented)</span></span></code></pre></div><h3 id="kernel-userspace-boundary" tabindex="-1">Kernel-to-Userspace Boundary <a class="header-anchor" href="#kernel-userspace-boundary" aria-label="Permalink to &quot;Kernel-to-Userspace Boundary {#kernel-userspace-boundary}&quot;">​</a></h3><p><strong>Is there a kernel→userspace transition in the gVisor sandbox?</strong></p><p>No. This is the key architectural difference:</p><p><strong>Phase 1 (community, with eBPF)</strong> — there IS a kernel boundary:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent process connect(&quot;api.internal&quot;, 443)</span></span>
<span class="line"><span>  → enters kernel socket layer      ← kernel space</span></span>
<span class="line"><span>  → eBPF cgroup/connect4 triggers    ← THE BOUNDARY!</span></span>
<span class="line"><span>    checks pid_iface_map: PID 12345 → ifindex=wf0</span></span>
<span class="line"><span>    forces ctx-&gt;user_ifindex = wf0</span></span>
<span class="line"><span>  → socket hijacked to wf0 TUN      ← enters sandbox network</span></span></code></pre></div><p><strong>Phase 2 (gVisor)</strong> — NO kernel boundary for networking:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent process connect(&quot;api.internal&quot;, 443)</span></span>
<span class="line"><span>  → intercepted by Sentry in user-space (never reaches kernel)</span></span>
<span class="line"><span>  → Go netstack handles everything in user-space</span></span>
<span class="line"><span>  → wireguard-go encrypts → raw socket sendmsg() → host kernel (L2 only)</span></span></code></pre></div><p>The raw socket at the end sends already-encrypted WireGuard payloads. The host kernel only does L2 forwarding — it never touches the IP stack. Policy was already enforced at the Sentry layer. eBPF is intentionally absent from the gVisor path.</p><p><strong>Why not add eBPF at the gVisor raw socket boundary?</strong></p><ol><li>Policy is already enforced at Sentry layer — adding eBPF would be redundant</li><li>Zero privilege is gVisor&#39;s core value — adding eBPF requires <code>CAP_BPF</code></li><li>Audit goes through Go channel (<code>ns.auditCh</code>), no need for eBPF ring buffer</li></ol><h3 id="infra-vs-gvisor" tabindex="-1">Infrastructure vs gVisor <a class="header-anchor" href="#infra-vs-gvisor" aria-label="Permalink to &quot;Infrastructure vs gVisor {#infra-vs-gvisor}&quot;">​</a></h3><p><strong>Should infrastructure nodes use gVisor?</strong></p><p>No. Infrastructure workloads (database replication, K8s Service mesh, cross-cluster bridging) should use the kernel TUN + eBPF path, not gVisor.</p><table tabindex="0"><thead><tr><th></th><th>Infrastructure</th><th>AI Agent Sandbox</th></tr></thead><tbody><tr><td>Traffic volume</td><td>High-throughput east-west (DB replication, mesh)</td><td>Low per-agent traffic</td></tr><tr><td>Performance requirement</td><td>Kernel line-rate</td><td>User-space is sufficient</td></tr><tr><td>Privilege acceptance</td><td>Ops nodes, root is fine</td><td>Zero-trust, avoid if possible</td></tr><tr><td>Syscall compatibility</td><td>DB/middleware may use obscure syscalls</td><td>Agent code is mostly normal network I/O</td></tr><tr><td>Overhead</td><td>eBPF near-zero overhead</td><td>gVisor ~25MB/sandbox acceptable</td></tr></tbody></table><p>gVisor&#39;s core value is <strong>zero privilege</strong> — giving an untrusted AI Agent process a complete but isolated network stack. Infrastructure nodes are controlled environments: operators already have root, so there&#39;s no reason to pay gVisor&#39;s performance and compatibility cost. The kernel eBPF path is the right choice for these workloads.</p><hr><h2 id="key-files-reference" tabindex="-1">Key Files Reference <a class="header-anchor" href="#key-files-reference" aria-label="Permalink to &quot;Key Files Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>internal/agent/ebpf/manager_community.go</code></td><td>Community stub (<code>//go:build !pro</code>)</td></tr><tr><td><code>internal/agent/ebpf/manager_pro.go</code></td><td>PRO eBPF Manager (<code>//go:build pro</code>)</td></tr><tr><td><code>internal/agent/ebpf/tc_ingress.bpf.c</code></td><td>eBPF C source (LPM Trie + Port Hash policy)</td></tr><tr><td><code>internal/agent/ebpf/tc_ingress_bpfel.go</code></td><td>bpf2go generated Go bindings</td></tr><tr><td><code>internal/agent/provision/enforcer_selector_pro.go</code></td><td>PRO eBPF capability detection</td></tr><tr><td><code>internal/agent/provision/enforcer_selector_community.go</code></td><td>Community: always ModeIPTables</td></tr><tr><td><code>internal/agent/provision/ebpf_enforcer.go</code></td><td>Creates eBPF enforcer, fallback to iptables</td></tr><tr><td><code>internal/agent/provision/provision_linux.go</code></td><td>iptables policy + NAT + FORWARD management</td></tr><tr><td><code>internal/agent/gvisor/sandbox.go</code></td><td>gVisor sandbox core (<code>//go:build pro</code>)</td></tr><tr><td><code>internal/agent/gvisor/shim_adapter.go</code></td><td>PolicyChecker + AuditWriter adapters</td></tr><tr><td><code>docs/superpowers/specs/2026-05-11-agent-sandbox-and-ecosystem-design.md</code></td><td>Full Phase 1/2/3 design doc</td></tr></tbody></table><h2 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><code>wf0</code></td><td>WireGuard TUN device name, Lattice data-plane entry point</td></tr><tr><td>TC ingress</td><td>Traffic Control ingress hook, eBPF program attach point</td></tr><tr><td>TCX</td><td>cilium/ebpf v0.21.0 TC attach API (replaces old netlink approach)</td></tr><tr><td>LPM Trie</td><td>Longest Prefix Match, eBPF map type for CIDR matching</td></tr><tr><td>Sentry</td><td>gVisor user-space kernel, intercepts sandbox process syscalls</td></tr><tr><td>PolicyCache</td><td>Go-layer policy cache, enforcement point for gVisor path</td></tr><tr><td>AF_PACKET</td><td>Raw socket used by gVisor to send encrypted packets to host kernel</td></tr><tr><td>LD_PRELOAD</td><td><code>liblattice_intercept.so</code> injection, community socket hijack fallback</td></tr><tr><td>seccomp notify</td><td>User-space seccomp notification, Phase 1 agent interception</td></tr></tbody></table><hr><p><em>Last updated: 2026-05-12</em></p>`,62)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
